size_t lg_base = binfo->lg_base;
size_t lg_first_group = binfo->lg_first_group;
size_t ngroup = binfo->ngroup;
size_t bit_offset = bit >> lg_base;
size_t group_mask = (1ULL << lg_first_group) - 1;
size_t group = bit_offset >> lg_first_group;
size_t group_shift = group * lg_first_group;
size_t group_bits = bit_offset & group_mask;
size_t index = group_shift + group_bits;
bitmap[index >> 6] ^= 1ULL << (index & 63);
// END_CODE

